    let permit = protocol::whitelist_admin::mint_new_whitelist(&admin_cap, &mut app, test_scenario::ctx(scenario));
    protocol::whitelist_admin::update_permission(&admin_cap, &mut app, object::id(&permit), protocol::whitelist_admin::liquidation(), true);

    let (collateral, refund) = protocol::liquidate::liquidate_as_coin<MainMarket, USDC, USDT>(
      &app,
      &permit,
        obligation_owner_cap.id(),
        &mut market, 
        usdc_coin, 
        &coin_registry, 
        &x_oracle, 
        &clock,
        scenario.ctx()
    );

    clock::destroy_for_testing(clock);

    // protocol will take 1 usdt
    assert_eq!(collateral.value(), 99_000_000);
    std::unit_test::destroy(collateral);
    // note that for 100 usdt, which worth only 99.8, with 0.05 liquidation incentive, it should take 95.142761 usdc at 0.999
    // refund is 800 - 95.142761 = 70.4857239
    // test is actually 704857238, some floating point inaccuracy
    assert_eq!(refund.value(), 704857238);
    std::unit_test::destroy(refund);

    // now make sure all debts are equal
    let reserve = market.get_reserve<MainMarket, USDC>();
    let (debt_amount, _) = market.borrow_obligation(obligation_owner_cap.id()).debt(std::type_name::with_defining_ids<USDC>()).snapshot();
    let emode_borrow_amount = protocol::emode::get_asset_borrow(market.emode_registry(), 0, std::type_name::with_defining_ids<USDC>());
    assert_eq!(debt_amount.ceil(), 1364857238);
    assert_eq!((*reserve.debt()).ceil(), 1364857238);
    assert_eq!(emode_borrow_amount, 1364857238);

    test_scenario::return_shared(x_oracle);
    test_scenario::return_shared(market);

    std::unit_test::destroy(admin_cap);
    std::unit_test::destroy(obligation_owner_cap);
    std::unit_test::destroy(app);
    std::unit_test::destroy(permit);
    std::unit_test::destroy(coin_registry);
    test_scenario::end(scenario_value);
  }
}

